// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        uint256 initialOwnerBalance = 200000000e18;
        uint256 transferAmount = 1e18;

        c.XBornID();

        assertEq(c.balanceOf(address(this)), initialOwnerBalance, "Owner balance should be initial after XBornID");

        c.transfer(address(1), transferAmount);

        uint256 expectedCorrect = initialOwnerBalance - transferAmount;

        assertTrue(c.balanceOf(address(this)) == expectedCorrect, "Owner balance should decrease by transfer amount");
    }
}
